head.script:
    // DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.onpageload = function() {
        var jsonData = [{col1:"afwafewfkjewlfae",col3:"a"},{col1:"c",col3:"c"},{col1:"d",col3:"d"},{col1:"b",col3:"b"}];
        dataList1.setJSON(jsonData);
    };

    scwin.onpageunload = function() {

    };


    scwin.gridView1_ongroupby = function(options) {
        scwin.test(options);
    };
    scwin.test = function(options){
        //debugger;
        var flag = true;
        if(flag) {
            options.closeGroup = true; 

            options.groupbyHeader = [{colSpan: "3", inputType: "expression", expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: "left" }];
            options.groupbyFooter = [
                {colSpan:"3",inputType: "expression", expression: " SUM('col2')", displayFormatter: "countFormatFunction", align: "center"}
            ];

            gridView1.groupby( options ); //실제 groupby 실행

        } else {
            return false; 
        }
    }
    var countFormatFunction = function( value ) {
        return "총판매수량 : " + value + " 개 ";
    };

	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}
	scwin.Dbclick = function(id) {
		var el = scwin.__getDom($p.id + id);
		scwin.fireDbClick(el);
	}

	scwin.checkVal = function() {
		let tdElement = (document.getElementById('gridView1_headerRowNumber_bodyRow_1') || document.getElementById('mf_gridView1_headerRowNumber_bodyRow_1'));
		let bgColor = window.getComputedStyle(tdElement).backgroundColor;
		return bgColor == 'rgb(223, 233, 248)';
	}
